  for i,n in enumerate(("requests","input_tokens","cached_tokens","output_tokens")):
   x=re.search(n+r"=([0-9]+)",l)
   if x:tokens[i]+=int(x.group(1))
print("mail_worker_requests_input_cached_output",tokens); print("events",rows[-14:])'","max_output_tokens":1200});text(r.output);

